with enriched as (select src.id, src.order_id, src.product_id, src.unit_price, p.brand from order_items src inner join products p on src.product_id <=> p.id), enriched_order_items as (select id, order_id, round(unit_price / sum(unit_price) over (partition by order_id), 4) as unit_price_share, count(unit_price) over (partition by brand) as brand_count_unit_price, round(unit_price / sum(unit_price) over (partition by brand, product_id), 4) as unit_price_share_2 from enriched), metrics as (select *, avg(unit_price_share_2) over (partition by order_id order by unit_price_share_2, id rows between 2 preceding and 1 preceding) as unit_price_share_2_avg_2_prior, sum(unit_price_share_2) over (order by unit_price_share_2, id rows between unbounded preceding and current row) as running_unit_price_share_2, lag(unit_price_share, 1) over (partition by order_id order by brand_count_unit_price, id) as prev_unit_price_share from enriched_order_items), filtered as (select *, brand_count_unit_price * running_unit_price_share_2 as brand_count_unit_price_times_running_unit_price_share_2 from metrics where prev_unit_price_share > 0.68) select s.id, s.order_id, s.unit_price_share, s.unit_price_share_2, s.unit_price_share_2_avg_2_prior, s.prev_unit_price_share, s.brand_count_unit_price_times_running_unit_price_share_2, (select min(x.cost) from shipments x where x.order_id = s.order_id) as min_shipment_cost from filtered s order by unit_price_share desc, unit_price_share_2;
